#include <bits/stdc++.h>

using namespace std;
#define ll long long

int parof(vector<ll>& parent, int x){
    if(parent[x] == x) return x;
    return parent[x] = parof(parent,parent[x]);
}

ll solve1(int n,int c, vector<int> perm,vector<int>cost){
    vector<ll> parent(n),size(n,1);
    for(int i=0;i<n;i++) parent[i] = i;
    for(int i=0;i<n;i++){
        int u = i,v = perm[u]-1;
        int pu = parof(parent,u),pv = parof(parent,v);
        // cout<<i<<" "<<pu<<" "<<pv<<endl;
        if(pu == pv) continue;
        parent[pu] = parof(parent,pv);
        cost[pv] += cost[pu];
        size[pv] += size[pu];
    }
    vector<bool> vis(n,false);
    ll ans = 0;
    for(int i=0;i<n;i++){
        int p = parof(parent,i);
        if(vis[p]) continue;
        vis[p] = true;
        ans += max(0LL,0LL+cost[p]-((size[p]-1)*c));
    }
    // for(int i=0;i<n;i++){
    //     cout << cost[i]<<" ";
    // }
    // cout << endl;
    // for(int i=0;i<n;i++){
    //     cout << parent[i]<<" ";
    // }
    // cout << endl;
    // for(int i=0;i<n;i++){
    //     cout << size[i]<<" ";
    // }
    // cout << endl;
    return ans;
}

ll solve2(int n,int c, vector<int> perm, vector<int> cost) {
    priority_queue<pair<int,int>> pq;
    for(int i=0;i<n;i++) pq.push({cost[i],i});
    unordered_set<int> s;
    ll ans = 0;
    while(!pq.empty()){
        auto [co,ind] = pq.top();pq.pop();
        if(s.find(ind) != s.end()) continue;
        if(co <= c) break;
        s.insert(ind);
        ans += co-c;
        if(s.find(perm[ind]-1) != s.end()){
            pq.push({cost[perm[ind]-1],ind});
        }
    }
    return ans;
}

int main() {
    // your code goes here
    int t;
    cin >> t;
    while (t--){
        int n,c;cin>>n>>c;
        vector<int> perm(n),cost(n);
        for(int i=0;i<n;i++) cin>>perm[i];
        for(int i=0;i<n;i++) cin>>cost[i];
        cout<<max(solve1(n,c,perm,cost),solve2(n,c,perm,cost))<<endl;
    }
}
